items.solution:
function crashRate(fn, inputs) {
  if (inputs.length === 0) return 0;
  let crashes = 0;
  for (const input of inputs) {
    try {
      fn(input);
    } catch (err) {
      crashes++;
    }
  }
  return Math.round((crashes / inputs.length) * 100);
}

