const SEVERITY_ORDER = ['low', 'medium', 'high', 'critical'];
function shouldBlockMerge(findings, threshold) {
  const thresholdIndex = SEVERITY_ORDER.indexOf(threshold);
  return findings.some((f) => SEVERITY_ORDER.indexOf(f.severity) >= thresholdIndex);
}

