items.solution:
function isOverdue(severity, daysSinceReported) {
  const SLA_DAYS = { critical: 7, high: 30, medium: 90, low: 180 };
  if (!(severity in SLA_DAYS)) return false;
  return daysSinceReported > SLA_DAYS[severity];
}
